  out[tag]=res[0]
 r=out[REF];c=out[TAG];bad=sorted({k for k in set(c['cls_eo'])|set(c['cls_oe']) if c['cls_eo'][k]+c['cls_oe'][k]>r['cls_eo'][k]+r['cls_oe'][k]+1},key=str)
 bats=lambda x:x['rec'][('bat','ours')]
 gain=100*(bats(c)[0]/max(1,bats(c)[1])-bats(r)[0]/max(1,bats(r)[1]))
