 fails={str(k):c['cls_eo'][k]+c['cls_oe'][k]-r['cls_eo'][k]-r['cls_oe'][k] for k in bad}
 fails.update({n:c[k][0]-r[k][0] for n,k in [('E→O total','eo'),('O→E total','oe')] if c[k][0]>r[k][0]})
 verdict='QUALIFIES' if ok else 'PENDING re-test' if gain>=8 and max(fails.values(),default=0)<=4 else 'no'
 result={'verdict':verdict,'gain_pp':gain,'own_bats':bats(c),'eo':c['eo'],'oe':c['oe'],'identity':[c['tp'],c['npred'],c['ntruth']],'bad_classes':[str(k) for k in bad],'failures':fails,'reference':{'own_bats':bats(r),'eo':r['eo'],'oe':r['oe'],'identity':[r['tp'],r['npred'],r['ntruth']]}}
 if not bats(r)[1] and not bats(c)[1]:result.update(applicability='No own-Bats truth: Bats-gain verdict inapplicable; assess per-class counts.')
 return result

def scans(tag,slices):
 per=collections.defaultdict(collections.Counter);eper=collections.defaultdict(collections.Counter);both=collections.defaultdict(collections.Counter);conf=collections.Counter();econf=collections.Counter()
